// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
  Img,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

const { fontFamily: interFamily } = loadInter();



export type BrainBeamAnimationProps = Record<string, any>;

const BrainBeamAnimation: React.FC<BrainBeamAnimationProps> = ({
  backgroundColor = "#111111",
  transparentBackground = false,
  durationInSeconds = 5,
  beamColor = "#f97316", // Vibrant orange
  brainImage = "https://malloy-files-c0ddahgefecthmcs.z03.azurefd.net/web/template_assets/images/brain.png",
  imageSizePercent = 45,
  imagePositionX = 72,
  imagePositionY = 50,
  beamTipPositionX = 66, // Roughly 72 - (45 * 0.25) taking visual width vs height into account
  beamTipPositionY = 50,
  textColor = "#ffffff",
  bracketColor = "rgba(255, 255, 255, 0.4)",
  text = "Everything to do with how\nthe human brain works",
  textSizePercent = 8, // Previously height * 0.08
  textPositionX = 5, // Previously width * 0.05
  textPositionY = 22, // Previously height * 0.22
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // --- Animation Timings & Springs ---
  // Delay the beam start slightly so the scene is established
  const beamStartFrame = 15;
  
  // Spring to drive the sweeping motion of the beam
  const sweepProgress = spring({
    frame: frame - beamStartFrame,
    fps,
    config: { damping: 14, mass: 0.9, stiffness: 80 },
  });

  // Fade in the head and brackets
  const sceneOpacity = interpolate(frame, [0, 10], [0, 1], {
    extrapolateRight: "clamp",
  });

  // --- Geometry & Layout ---
  // Position the image based on user-defined schema properties
  const imageSize = height * (imageSizePercent / 100); 
  const imageCx = width * (imagePositionX / 100);
  const imageCy = height * (imagePositionY / 100);

  // Determine the exact point on the canvas where the beam originates
  // Now controlled by custom properties
  const absoluteEyeX = width * (beamTipPositionX / 100);
  const absoluteEyeY = height * (beamTipPositionY / 100);

  // --- Beam Animation Logic ---
  // The beam is a polygon with 3 points: Eye (fixed), TopLeft (animated), BottomLeft (animated)
  
  // Initial state: Beam points downwards, out of view
  const startTlY = height + 400;
  const startBlY = height + 1000;
  
  // Final state: Beam covers the top-left area
  const endTlY = -height * 0.2; // Overshoot top to ensure full coverage
  const endBlY = height * 0.55;

  const currentTlY = interpolate(sweepProgress, [0, 1], [startTlY, endTlY]);
  const currentBlY = interpolate(sweepProgress, [0, 1], [startBlY, endBlY]);

  // Construct the polygon points for both SVG rendering and CSS clipping
  const beamPoints = `0,${currentTlY} 0,${currentBlY} ${absoluteEyeX},${absoluteEyeY}`;
  // CSS clip-path requires px units and standard syntax
  const cssClipPath = `polygon(0px ${currentTlY}px, 0px ${currentBlY}px, ${absoluteEyeX}px ${absoluteEyeY}px)`;

  // --- Bracket Configuration ---
  const bracketSize = 40;
  const bracketThickness = 2;
  // Box encompassing the image for brackets
  const boxW = imageSize * 1.2;
  const boxH = imageSize * 1.2;
  const boxCx = imageCx;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      
      {/* 1. Background Scene (Image and Brackets) */}
      <AbsoluteFill style={{ opacity: sceneOpacity }}>
        
        {/* Brackets */}
        <AbsoluteFill>
          {/* Top Left */}
          <div style={{
            position: "absolute", left: boxCx - boxW/2, top: imageCy - boxH/2,
            width: bracketSize, height: bracketSize,
            borderTop: `${bracketThickness}px solid ${bracketColor}`,
            borderLeft: `${bracketThickness}px solid ${bracketColor}`
          }} />
          {/* Top Right */}
          <div style={{
            position: "absolute", left: boxCx + boxW/2 - bracketSize, top: imageCy - boxH/2,
            width: bracketSize, height: bracketSize,
            borderTop: `${bracketThickness}px solid ${bracketColor}`,
            borderRight: `${bracketThickness}px solid ${bracketColor}`
          }} />
          {/* Bottom Left */}
          <div style={{
            position: "absolute", left: boxCx - boxW/2, top: imageCy + boxH/2 - bracketSize,
            width: bracketSize, height: bracketSize,
            borderBottom: `${bracketThickness}px solid ${bracketColor}`,
            borderLeft: `${bracketThickness}px solid ${bracketColor}`
          }} />
          {/* Bottom Right */}
          <div style={{
            position: "absolute", left: boxCx + boxW/2 - bracketSize, top: imageCy + boxH/2 - bracketSize,
            width: bracketSize, height: bracketSize,
            borderBottom: `${bracketThickness}px solid ${bracketColor}`,
            borderRight: `${bracketThickness}px solid ${bracketColor}`
          }} />
        </AbsoluteFill>

        {/* Brain Image */}
        <AbsoluteFill style={{ display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
          <div style={{
            position: "absolute",
            left: imageCx - imageSize / 2,
            top: imageCy - imageSize / 2,
            width: imageSize,
            height: imageSize,
            display: "flex",
            justifyContent: "center",
            alignItems: "center"
          }}>
            <Img 
              src={brainImage} 
              style={{
                maxWidth: '100%',
                maxHeight: '100%',
                objectFit: 'contain'
              }}
            />
          </div>
        </AbsoluteFill>
      </AbsoluteFill>

      {/* 2. The Sweeping Beam */}
      <AbsoluteFill>
        <svg width={width} height={height} viewBox={`0 0 ${width} ${height}`}>
          <polygon points={beamPoints} fill={beamColor} />
        </svg>
      </AbsoluteFill>

      {/* 3. The Revealed Text (Clipped exactly to the beam's shape) */}
      {/* We apply the CSS clip-path to this container so the text is ONLY visible where the beam is */}
      <AbsoluteFill style={{ clipPath: cssClipPath }}>
        <div style={{
          position: "absolute",
          left: width * (textPositionX / 100),
          top: height * (textPositionY / 100),
          width: width * 0.45,
          transform: "rotate(8deg)", // Angle text slightly down to right to match beam flow
          transformOrigin: "left center",
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          fontFamily: interFamily,
        }}>
          <h1 style={{
            margin: 0,
            color: textColor,
            fontSize: `${height * (textSizePercent / 100)}px`, // Responsive font size controlled by schema
            fontWeight: 800,
            lineHeight: 1.1,
            letterSpacing: "-0.03em",
            whiteSpace: "pre-wrap",
          }}>
            {text}
          </h1>
        </div>
      </AbsoluteFill>

    </AbsoluteFill>
  );
};

export default BrainBeamAnimation;